p=1025; 
v=12; 
g=9.8; 
Mbuoy=1000; 
Mtube=10; 
Mdrum=100; 
Mball=1200; 
Ltube=1; 
Dtube=0.05; 
Ldrum=1; 
Ddrum=0.3; 
s=22.05; 
m=7; 
Gbuoy=Mbuoy*g; 
Gtube=Mtube*g; 
Fftube=p*g*Ltube*pi*0.25*Dtube*Dtube; 
temp=Gtube-Fftube; 
Ffdrum=p*g*Ldrum*0.25*pi*Ddrum*Ddrum; 
Gdrum=Mdrum*g; 
Gball=Mball*g; 
Ffball=Gball/7.46;%7.65/1.025=7.46 
realh=100; 
judge=100; 

% h=2-((Gbuoy+4*temp+Gdrum+Gball-Ffdrum-Ffball+0.87*m*s)/(p*g*pi)); 
% realh=0; 
% theta0=pi/2; 
% Fwind=2*0.625*h*v*v; 
% F0=Fwind/sin(theta0); 
% a=0.87*m*g; 
% b=F0*cos(theta0); 
% c=F0*sin(theta0); 
% y=(c/a)*(1/cos(atan((a*s+b)/c))-1/cos(atan(b/c))); 

for h=1:0.0001:1.5 
 Fwind=2*0.625*h*v*v; 
 Ff=p*g*pi*(2-h); 
 theta1=atan(Fwind/(Ff-Gbuoy)); 
 F1=Fwind/sin(theta1); 
 theta2=atan((F1*sin(theta1))/(F1*cos(theta1)-temp)); 
