 a=0.87*m*g; 
 b=F0*cos(theta0); 
 c=F0*sin(theta0); 
 y=(c/a)*(1/cos(atan((a*s+b)/c))-1/cos(atan(b/c))); 

 alpha1=(F2*theta2+F1*theta1)/(F1+F2); 
