 H2=cos(alpha2); 
 H3=cos(alpha3); 
 H4=cos(alpha4); 
 Hdrum=cos(Alpha); 
 Hriver=2-h+H1+H2+H3+H4+Hdrum+y; 
 if(judge>abs(18-Hriver)) 
 realh=h; 
 judge=abs(18-Hriver); 
 end 
end 
